(() => { 'use strict'; const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function add(symbol,cls,i){const node=document.createElement('span');node.className=cls;node.textContent=symbol;node.style.setProperty('--x',`${Math.random()*96}%`);node.style.setProperty('--y',`${Math.random()*100}%`);node.style.setProperty('--size',`${10+Math.random()*18}px`);node.style.setProperty('--duration',`${4+Math.random()*6}s`);node.style.setProperty('--delay',`${Math.random()*3}s`);node.style.setProperty('--color',['#ffd777','#ffb38f','#f7bad8','#b7c8ff'][i%4]);document.getElementById('decorations').append(node)}function init(){if(reduced)return;for(let i=0;i<28;i++)add(i%3?'✦':'❀',i%3?'decor-spark':'decor-flower',i)}function celebrate(){if(reduced)return;for(let i=0;i<42;i++)add(i%4===0?'♥':(i%2?'✦':'❀'),'decor-heart',i)}window.Effects={init,celebrate}})();
